breach.segment:
// Alert threshold (percent of disk quota). A full disk makes the instance stop
// accepting writes. Lower to 80 for an earlier warning, raise if automatic
// storage increase is enabled and you only want to catch it failing to keep up.
WHERE disk_used_pct >= 90
| KEEP database_id, disk_used_pct, free_gib, bytes_used, quota
| SORT disk_used_pct DESC
| LIMIT 100
